//! Fetch errors and their mapping onto the contract [`ErrorCode`] / [`BlockReason`].
//!
//! `Display` strings are generated by Secure Web and never contain response content, header
//! values or URL text: they may end up in an MCP error `message`.

use std::time::Duration;

use secure_web_core::error::ErrorCode;
use secure_web_core::model::BlockReason;
use secure_web_security::ssrf::GuardError;

/// Why a redirect hop was refused (`REDIRECT_BLOCKED`, `BlockReason::RedirectViolation`).
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
pub enum RedirectViolation {
    /// The `Location` target failed the URL guard (SSRF range, denied host, scheme, userinfo,
    /// ambiguous IPv4 literal, DNS failure, …).
    #[error("redirect target rejected by the URL guard ({})", .0.code())]
    Guard(GuardError),
    /// More than `fetch.maxRedirects` hops.
    #[error("more than {max} redirects")]
    TooManyHops {
        /// The configured cap.
        max: u32,
    },
    /// A hop pointed back at a URL already visited in this chain.
    #[error("redirect loop")]
    Loop,
    /// `https` → `http` while `fetch.allowRedirectDowngrade` is false.
    #[error("redirect downgrades https to http")]
    Downgrade,
    /// `Location` is not valid visible ASCII or does not resolve to a URL.
    #[error("invalid redirect Location")]
    InvalidLocation,
    /// The URL validated from the raw `Location` text is not the URL a client would follow
    /// (the raw text and the resolved URL disagree), so neither is trusted.
    #[error("redirect Location is ambiguous")]
    InconsistentLocation,
}

/// A failed fetch.
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
pub enum FetchError {
    /// A redirect hop violated policy → `REDIRECT_BLOCKED`.
    #[error("redirect blocked: {0}")]
    RedirectBlocked(RedirectViolation),
    /// Connect timeout or the whole-fetch deadline → `FETCH_TIMEOUT` (retryable).
    #[error("fetch timed out")]
    Timeout,
    /// The final response was not `2xx` → `FETCH_FAILED`; retryable for `5xx` and `429`.
    #[error("HTTP status {status}")]
    Status {
        /// Final HTTP status.
        status: u16,
        /// `Retry-After` delay on `429`/`503`, when present and `fetch.respectRetryAfter` is on.
        retry_after: Option<Duration>,
    },
    /// Connection, protocol or body-decoding failure → `FETCH_FAILED`.
    #[error("network error")]
    Network {
        /// Whether a retry may succeed (connection-level failures) or not (corrupt body).
        retryable: bool,
    },
    /// The decompressed body (or its declared `Content-Length`) exceeds the limit →
    /// `CONTENT_TOO_LARGE`. The stream was aborted; nothing past the limit was kept.
    #[error("response exceeds {limit} bytes")]
    ContentTooLarge {
        /// The limit that applied (`maxPageBytes`, or `maxJsonBytes` for JSON).
        limit: u64,
        /// Largest amount of body data held in memory at once: decoded bytes kept plus the
        /// network chunk being processed. Bounded by `limit + one chunk`.
        peak_buffered_bytes: u64,
    },
    /// The `Content-Type` is not one of the supported types → `UNSUPPORTED_CONTENT_TYPE`.
    /// Returned before the body is read.
    #[error("unsupported content type")]
    UnsupportedContentType {
        /// Normalized MIME essence (token characters only, at most 64 bytes). Untrusted text:
        /// never expose it to an agent without normalization.
        essence: String,
    },
    /// The `Content-Encoding` is not `gzip`, `deflate` or `identity`, or stacks several
    /// encodings → `UNSUPPORTED_CONTENT_TYPE`.
    #[error("unsupported content encoding")]
    UnsupportedContentEncoding,
    /// The HTTP client could not be built (TLS setup) → `INTERNAL`.
    #[error("HTTP client setup failed")]
    Client,
}

impl FetchError {
    /// The contract error code.
    pub fn code(&self) -> ErrorCode {
        match self {
            FetchError::RedirectBlocked(_) => ErrorCode::RedirectBlocked,
            FetchError::Timeout => ErrorCode::FetchTimeout,
            FetchError::Status { .. } | FetchError::Network { .. } => ErrorCode::FetchFailed,
            FetchError::ContentTooLarge { .. } => ErrorCode::ContentTooLarge,
            FetchError::UnsupportedContentType { .. } | FetchError::UnsupportedContentEncoding => {
                ErrorCode::UnsupportedContentType
            }
            FetchError::Client => ErrorCode::Internal,
        }
    }

    /// Whether retrying the same fetch later may succeed. The crawler decides whether to.
    pub fn retryable(&self) -> bool {
        match self {
            FetchError::Timeout => true,
            FetchError::Status { status, .. } => *status == 429 || (500..=599).contains(status),
            FetchError::Network { retryable } => *retryable,
            FetchError::RedirectBlocked(_)
            | FetchError::ContentTooLarge { .. }
            | FetchError::UnsupportedContentType { .. }
            | FetchError::UnsupportedContentEncoding
            | FetchError::Client => false,
        }
    }

    /// The block reason when this failure makes the page a `BlockedDocument` (a policy
    /// violation), `None` for ordinary fetch failures.
    pub fn block_reason(&self) -> Option<BlockReason> {
        match self {
            FetchError::RedirectBlocked(_) => Some(BlockReason::RedirectViolation),
            FetchError::ContentTooLarge { .. } => Some(BlockReason::ContentTooLarge),
            FetchError::UnsupportedContentType { .. } | FetchError::UnsupportedContentEncoding => {
                Some(BlockReason::UnsupportedContentType)
            }
            FetchError::Timeout
            | FetchError::Status { .. }
            | FetchError::Network { .. }
            | FetchError::Client => None,
        }
    }

    /// `Retry-After` delay, if the server sent one on `429`/`503`.
    pub fn retry_after(&self) -> Option<Duration> {
        match self {
            FetchError::Status { retry_after, .. } => *retry_after,
            _ => None,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn status_retryability_follows_the_policy() {
        let status = |status| FetchError::Status {
            status,
            retry_after: None,
        };
        assert!(status(500).retryable());
        assert!(status(503).retryable());
        assert!(status(429).retryable());
        assert!(!status(404).retryable());
        assert!(!status(403).retryable());
        assert_eq!(status(404).code(), ErrorCode::FetchFailed);
    }

    #[test]
    fn policy_violations_carry_a_block_reason() {
        let redirect = FetchError::RedirectBlocked(RedirectViolation::Loop);
        assert_eq!(redirect.code(), ErrorCode::RedirectBlocked);
        assert_eq!(
            redirect.block_reason(),
            Some(BlockReason::RedirectViolation)
        );
        assert!(!redirect.retryable());
        assert_eq!(FetchError::Timeout.block_reason(), None);
        assert_eq!(FetchError::Timeout.code(), ErrorCode::FetchTimeout);
    }
}
